<?php
require_once __DIR__.'/../app/lib/Db.php';require_once __DIR__.'/../app/lib/Security.php';$config=require __DIR__.'/../app/config.php';$pdo=Db::pdo();Security::start();$u=Security::requireRole(['admin','data_editor','reviewer','super_admin']);$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$method=$_SERVER['REQUEST_METHOD']??'GET';function out($d,int $s=200){http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}function body(){return json_decode(file_get_contents('php://input'),true)?:[];}
if($method!=='GET'){Security::sameOrigin($config);Security::requireCsrf();Security::rateLimit($pdo,'admin-write',60,60);}
if($path==='/api/admin/summary'&&$method==='GET'){$counts=[];foreach(['products','evidence_sources','users','consultations'] as $t)$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM {$t}")->fetchColumn();$counts['unverified_evidence']=(int)$pdo->query("SELECT COUNT(*) FROM evidence_sources WHERE verification_status<>'verified'")->fetchColumn();out($counts);}
if($path==='/api/admin/products'&&$method==='GET'){$q=$pdo->query("SELECT p.id,p.name,p.slug,p.status,p.last_reviewed_at,v.name vendor,c.name category FROM products p LEFT JOIN vendors v ON v.id=p.vendor_id LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.name");out(['products'=>$q->fetchAll()]);}
if(preg_match('#^/api/admin/products/(\d+)$#',$path,$m)&&$method==='PATCH'){$id=(int)$m[1];$before=$pdo->prepare("SELECT id,name,short_description,status,website_url,last_reviewed_at FROM products WHERE id=?");$before->execute([$id]);$old=$before->fetch();if(!$old)out(['error'=>'not_found'],404);$b=body();$status=$b['status']??$old['status'];if(in_array($status,['verified','published'],true)&&!in_array($u['role'],['reviewer','super_admin','admin'],true))out(['error'=>'reviewer_required'],403);$name=trim($b['name']??$old['name']);$desc=$b['short_description']??$old['short_description'];$url=$b['website_url']??$old['website_url'];$pdo->prepare("UPDATE products SET name=?,short_description=?,website_url=?,status=?,last_reviewed_at=CASE WHEN ? IN ('verified','published','active') THEN NOW() ELSE last_reviewed_at END WHERE id=?")->execute([$name,$desc,$url,$status,$status,$id]);$after=$pdo->prepare("SELECT id,name,short_description,status,website_url,last_reviewed_at FROM products WHERE id=?");$after->execute([$id]);$new=$after->fetch();Security::audit($pdo,(int)$u['id'],'PRODUCT_UPDATE','product',(string)$id,$old,$new);out(['product'=>$new]);}
if($path==='/api/admin/evidence'&&$method==='GET'){$q=$pdo->query("SELECT e.id,p.name product,e.source_title,e.source_url,e.source_type,e.verification_status,e.confidence,e.checked_at FROM evidence_sources e JOIN products p ON p.id=e.product_id ORDER BY e.checked_at DESC");out(['evidence'=>$q->fetchAll()]);}
if(preg_match('#^/api/admin/evidence/(\d+)$#',$path,$m)&&$method==='PATCH'){$id=(int)$m[1];$st=$pdo->prepare("SELECT * FROM evidence_sources WHERE id=?");$st->execute([$id]);$old=$st->fetch();if(!$old)out(['error'=>'not_found'],404);$b=body();$status=$b['verification_status']??$old['verification_status'];$confidence=$b['confidence']??$old['confidence'];$notes=$b['notes']??$old['notes'];$pdo->prepare("UPDATE evidence_sources SET verification_status=?,confidence=?,notes=?,checked_at=NOW() WHERE id=?")->execute([$status,$confidence,$notes,$id]);$st->execute([$id]);$new=$st->fetch();Security::audit($pdo,(int)$u['id'],'EVIDENCE_UPDATE','evidence',(string)$id,$old,$new);out(['evidence'=>$new]);}
out(['error'=>'not_found'],404);